begin;
create table app.result_publication_revisions(
 school_id uuid not null,id uuid not null default gen_random_uuid(),result_id uuid not null,learner_id uuid not null,revision integer not null check(revision>0),parent_visible boolean not null,reason text not null check(length(btrim(reason))between 1 and 2000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,result_id,revision),foreign key(school_id,result_id,learner_id)references internal.academic_result_sources(school_id,id,learner_id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id)
);
alter table app.result_publication_revisions enable row level security;alter table app.result_publication_revisions force row level security;revoke all on app.result_publication_revisions from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
create trigger publication_immutable before update or delete on app.result_publication_revisions for each row execute function internal.academic_history_immutable();create trigger publication_no_truncate before truncate on app.result_publication_revisions for each statement execute function internal.academic_history_immutable();
create function internal.result_parent_published(target_school uuid,target_result uuid)returns boolean language sql stable security definer set search_path=''as $$
 select coalesce((select publication.parent_visible from app.result_publication_revisions publication where publication.school_id=target_school and publication.result_id=target_result order by publication.revision desc limit 1),
 (select coalesce(numeric.parent_visible,rubric.parent_visible)from internal.academic_result_sources source left join app.result_revisions numeric on numeric.school_id=source.school_id and numeric.id=source.numeric_result_id left join app.rubric_result_revisions rubric on rubric.school_id=source.school_id and rubric.id=source.rubric_result_id where source.school_id=target_school and source.id=target_result),false)
$$;
create function internal.result_source_read_allowed(target_school uuid,target_result uuid)returns boolean language sql stable security definer set search_path=''as $$
 select coalesce(exists(select 1 from internal.academic_result_sources source join app.assessments assessment on assessment.school_id=source.school_id and assessment.id=(internal.native_academic_source(target_school,target_result)->>'assessmentId')::uuid where source.school_id=target_school and source.id=target_result and"authorization".can_read_academic_source(target_school,source.learner_id,internal.result_parent_published(target_school,target_result),assessment.id)and("authorization".current_role(target_school)<>'parent'or"authorization".current_learner_course(target_school,assessment.course_id,source.learner_id))),false)
$$;
create function internal.read_result_publication(target_result uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();source jsonb;revision integer;begin
 if not internal.result_source_read_allowed(school,target_result)then raise exception 'Result publication source denied'using errcode='42501';end if;source:=internal.native_academic_source(school,target_result);select coalesce(max(publication.revision),0)into revision from app.result_publication_revisions publication where publication.school_id=school and publication.result_id=target_result;
 return jsonb_build_object('id',target_result,'parentVisible',internal.result_parent_published(school,target_result),'publicationRevision',revision,'resultRevision',(source->>'revision')::integer);
end$$;
create function internal.publish_result_parent(target_result uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();source jsonb;latest integer;reservation jsonb;receipt jsonb;begin
 if not"authorization".academic_access(school)or"authorization".current_role(school)is null or"authorization".current_role(school)not in('teacher','admin')then raise exception 'Human result publication denied'using errcode='42501';end if;
 if payload is null or jsonb_typeof(payload)<>'object'or payload-'parentVisible'-'expectedPublicationRevision'-'expectedResultRevision'-'reason'-'confirmPublication'<>'{}'::jsonb or payload->'confirmPublication'is distinct from'true'::jsonb or jsonb_typeof(payload->'parentVisible')is distinct from'boolean'or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 2000 or jsonb_typeof(payload->'expectedPublicationRevision')is distinct from'number'or payload->>'expectedPublicationRevision'!~'^[0-9]+$'or jsonb_typeof(payload->'expectedResultRevision')is distinct from'number'or payload->>'expectedResultRevision'!~'^[1-9][0-9]*$'then raise exception 'Explicit current publication review required'using errcode='22023';end if;
 source:=internal.native_academic_source(school,target_result);
 if source is null or not"authorization".can_manage_course(school,(source->>'courseId')::uuid)or not"authorization".current_learner_course(school,(source->>'courseId')::uuid,(source->>'learnerId')::uuid)or not internal.result_source_read_allowed(school,target_result)then raise exception 'Current native result publication scope denied'using errcode='42501';end if;
 -- Publication is access authority for retained evidence, not an academic work write.
 perform 1 from app.courses where school_id=school and id=(source->>'courseId')::uuid for update;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':result-publication:'||target_result::text,0));
 source:=internal.native_academic_source(school,target_result);
 if source is null or not"authorization".can_manage_course(school,(source->>'courseId')::uuid)or not"authorization".current_learner_course(school,(source->>'courseId')::uuid,(source->>'learnerId')::uuid)or not internal.result_source_read_allowed(school,target_result)then raise exception 'Current native result publication scope denied'using errcode='42501';end if;
 reservation:=internal.begin_command(command_key,'result.publication',fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;if reservation->>'state'<>'NEW'then raise exception 'Publication command in progress'using errcode='22023';end if;
 select coalesce(max(revision),0)into latest from app.result_publication_revisions where school_id=school and result_id=target_result;
 if latest is distinct from(payload->>'expectedPublicationRevision')::integer or(source->>'revision')::integer is distinct from(payload->>'expectedResultRevision')::integer then raise exception 'Publication or native result revision changed'using errcode='22023';end if;
 insert into app.result_publication_revisions(school_id,result_id,learner_id,revision,parent_visible,reason,actor_id)values(school,target_result,(source->>'learnerId')::uuid,latest+1,(payload->>'parentVisible')::boolean,btrim(payload->>'reason'),"authorization".actor_id());
 receipt:=jsonb_build_object('id',target_result,'parentVisible',(payload->>'parentVisible')::boolean,'publicationRevision',latest+1,'resultRevision',(source->>'revision')::integer);
 perform internal.append_audit('result.publication','result',target_result,request_id,'succeeded',jsonb_build_object('parentVisible',(payload->>'parentVisible')::boolean,'publicationRevision',latest+1));perform internal.enqueue_event('curriculum.configured','curriculum',target_result,latest+1,jsonb_build_object('publication',true),md5('result-publication:'||"authorization".actor_id()::text||':'||command_key));perform internal.finish_command(command_key,'result.publication',fingerprint,receipt);return receipt;
end$$;
drop policy results_read on app.result_revisions;create policy results_read on app.result_revisions for select to cuevo_api using(internal.result_source_read_allowed(school_id,id));
drop policy rubric_results_read on app.rubric_result_revisions;create policy rubric_results_read on app.rubric_result_revisions for select to cuevo_api using(internal.result_source_read_allowed(school_id,id));
drop policy evidence_read on app.academic_evidence;create policy evidence_read on app.academic_evidence for select to cuevo_api using(internal.result_source_read_allowed(school_id,result_id));
drop policy rubric_evidence_read on app.rubric_evidence;create policy rubric_evidence_read on app.rubric_evidence for select to cuevo_api using(internal.result_source_read_allowed(school_id,result_id));
drop policy current_results_read on app.current_results;create policy current_results_read on app.current_results for select to cuevo_api using(internal.result_source_read_allowed(school_id,result_id));
drop policy current_rubric_results_read on app.current_rubric_results;create policy current_rubric_results_read on app.current_rubric_results for select to cuevo_api using(internal.result_source_read_allowed(school_id,result_id));
-- Every parent native candidate and source disclosure uses current exact publication.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.list_parent_current_results_scoped(integer,uuid,uuid)'::regprocedure);
 if position('and r.parent_visible'in definition)=0 or position('and ev.parent_visible'in definition)=0 then raise exception 'Parent publication candidate source changed'using errcode='22023';end if;
 definition:=replace(definition,'and r.parent_visible','and internal.result_parent_published(school,r.id)');definition:=replace(definition,'and ev.parent_visible','and internal.result_parent_published(school,r.id)');definition:=replace(definition,'''parentVisible'',b.parent_visible','''parentVisible'',internal.result_parent_published(school,b.id)');execute definition;
 definition:=pg_get_functiondef('internal.native_academic_source_allowed(uuid,uuid,boolean)'::regprocedure);anchor:='coalesce(numeric.parent_visible,rubric.parent_visible)';if position(anchor in definition)=0 then raise exception 'Native publication source changed'using errcode='22023';end if;execute replace(definition,anchor,'internal.result_parent_published(target_school,target_result)');
 definition:=pg_get_functiondef('internal.read_academic_revision_page(uuid,integer,uuid)'::regprocedure);
 if position('anchor.parent_visible'in definition)=0 or position('source.parent_visible'in definition)=0 then raise exception 'Native history publication source changed'using errcode='22023';end if;
 definition:=replace(definition,'anchor.parent_visible','internal.result_parent_published(school,source_result)');definition:=replace(definition,'source.parent_visible','internal.result_parent_published(school,source.id)');definition:=replace(definition,'''parentVisible'',r.parent_visible','''parentVisible'',internal.result_parent_published(school,r.id)');execute definition;
 definition:=pg_get_functiondef('internal.portfolio_source(text,uuid,boolean)'::regprocedure);
 if position('r.parent_visible and e.parent_visible'in definition)=0 then raise exception 'Portfolio publication source changed'using errcode='22023';end if;
 definition:=replace(definition,'''parentVisible'',r.parent_visible','''parentVisible'',internal.result_parent_published(r.school_id,r.id)');definition:=replace(definition,'r.learner_id,r.parent_visible','r.learner_id,internal.result_parent_published(r.school_id,r.id)');definition:=replace(definition,'r.parent_visible and e.parent_visible','internal.result_parent_published(r.school_id,r.id)');execute definition;
 definition:=pg_get_functiondef('internal.current_native_sources(uuid,uuid)'::regprocedure);anchor:='result.created_at,result.parent_visible';if position(anchor in definition)=0 then raise exception 'Learner projection publication source changed'using errcode='22023';end if;execute replace(definition,anchor,'result.created_at,internal.result_parent_published(target_school,result.id)');
end$$;
revoke execute on function internal.result_parent_published(uuid,uuid),internal.result_source_read_allowed(uuid,uuid),internal.read_result_publication(uuid),internal.publish_result_parent(uuid,jsonb,text,text,text)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.result_source_read_allowed(uuid,uuid),internal.read_result_publication(uuid),internal.publish_result_parent(uuid,jsonb,text,text,text)to cuevo_api;
commit;
